/* المُلهم، «تعلّم»: مكتبة المؤلفين، كتاب «مشكلات الأطفال» */
window.HH_LIB=window.HH_LIB||{};
window.HH_LIB["kids"]={"id":"kids","title":"مشكلات الأطفال","sub":"تشخيص وعلاج لأهم عشر مشكلات يعاني منها الأطفال","author":"أ.د. عبد الكريم بكار","coauthors":[],"translator":"","publisher":"دار السلام للطباعة والنشر والتوزيع والترجمة، القاهرة","year":"2010","edition":"الأولى","series":"التربية الرشيدة (5)","lead":"الجزء الخامس من سلسلة التربية الرشيدة، خصصه المؤلف «للحديث عن أهم مشكلات الأطفال التي يعاني منها الأطفال وكثير من الآباء والأمهات؛ بغية توفير ثقافة تربوية تساعدهم على فهم تلك المشكلات والتعامل معها». يعرض عشر مشكلات، لكل منها تعريفها ومظاهرها وأسبابها وطرق علاجها بأسلوب عملي تتخلله قصص واقعية.","audience":"الآباء والمربون والمعلمون","bio":"حصل على البكالوريوس من كلية اللغة العربية بجامعة الأزهر (1393ه/1973م)، وعلى الماجستير في عام (1395ه/1975م)، والدكتوراه في عام (1399ه/1979م) من قسم أصول اللغة بالكلية نفسها بجامعة الأزهر","chapters":[{"k":"c1","t":"الكذب","q":"لماذا يكذب الطفل، وكيف نعيده إلى الصدق؟","essence":"الكذب مكتسب، ويعالج بمعرفة دافعه","kw":["الخوف من العقاب","التقليد","الثقة بالنفس"],"sections":[{"t":"تعريف الكذب وخطورته","pg":11,"key":"حين نتحدث عن كذب الأطفال، فإننا نقصد مخالفة كلام الإنسان لما يعتقده بقصد التضليل وإخفاء الحقيقة","p":["مشكلة الكذب من أكبر المشكلات التي يقع فيها الأطفال، ويزداد خوفنا حين ينتشر الكذب بين الكبار؛ لأن ذلك يشبه الوباء حين ينتشر بين الأطباء!"],"items":[{"h":"التستر على الخطأ","x":"الكذب يجعل صاحبه يستسهل الوقوع في الخطأ ما دام يجد فيه ما ينجيه من العواقب، فيصير إدمانه مفتاحًا لانحراف كبير."},{"h":"صلته بالغش والسرقة","x":"دلت دراسات على جرائم الأحداث أن من اتصف بالكذب يتصف عادة بالغش والسرقة، وكلها متفرعة من صفة الخيانة."},{"h":"الموقف النبوي","x":"كان النبي صلى الله عليه وسلم إذا اطلع على كذبة من أحد أهل بيته أعرض عنه حتى يحدث توبة، وهو موقف عملي فيه الهجر والإعراض."}]},{"t":"لماذا يكذب الطفل؟","pg":13,"key":"علينا في البداية أن نؤكد على أن الكذب ليس صفة فطرية أو وراثية لدى الطفل، أي إنها صفة مكتسبة تتكون لدى الطفل عن طريق التعليم والتقليد وتراكم الخبرة","p":[],"items":[{"h":"القدرة اللغوية","x":"طلاقة اللسان والمهارة في صياغة الجمل تدفع الطفل إلى النطق بمزيد من الكلمات دون التأكد من مطابقتها للواقع."},{"h":"خصوبة الخيال","x":"كالطفل الذي يقول إنه رأى قطة لها قرون بعد أن رأى خروف العيد."}]},{"t":"دوافع الكذب","pg":14,"key":"وهذا يعود إلى عامل الخوف، لكنه يحمِّل الآباء القساة مسؤولية انحراف أبنائهم","p":[],"items":[{"h":"الخوف من العقاب","x":"من أكثر ما يدفع الطفل إلى الكذب، وتذكر دراسة أوردها المؤلف أن نحو 70% من كذب الأطفال يرجع إليه."},{"h":"قسوة الآباء","x":"كلما ازدادت القسوة واللجوء إلى الضرب لحمل الطفل على الإقرار لجأ إلى الكذب ثم أدمنه."},{"h":"طلب الإعجاب","x":"يكذب ليحدث لذة عند مستمعيه، كأن يفاخر بثياب ليست عنده أو يدعي قدرات خارقة."},{"h":"الحصول على الأشياء","x":"كأن يدعي أن معلمه طلب منه شراء أدوات وهو يريد المال للحلوى أو اللعب."},{"h":"الدافع العدواني","x":"كأن ينسب كسر تحفة إلى أخيه ليوقع عليه العقوبة."},{"h":"التقليد","x":"يتعلم الكذب من أبويه، كمن أوهمه أبواه أنهما نائمان ثم خرجا، أو وعدته أمه بمدينة الملاهي فإذا هو في عيادة الأسنان."}]},{"t":"كيف نعالج الكذب؟","pg":16,"key":"حاول ألا تحشر الطفل في زاوية ضيقة، وتطلب منه الاعتراف بجرم ارتكبه أو خطأ وقع فيه","p":["الكذب عند ابن أربع أو خمس سنوات، لا يشكل شيئًا مقلقًا؛ وذلك لأن الطفل في هذه المرحلة لا يستطيع التمييز بين الخيال والواقع، ولا يدرك ضرورة مطابقة ما يقوله لواقع الحال."],"items":[{"h":"تعزيز الثقة بالنفس","x":"بعض الأطفال يكذبون ليثبتوا لأنفسهم فضائل ليست لهم تعويضًا عن الشعور بالنقص، فتعزيز ثقتهم يقلل لجوءهم إلى الكذب."},{"h":"القدوة في الأسرة","x":"لن يلتزم الأطفال بالصدق في أسرة يكذب فيها الأب على الأم والأخ الكبير على الأخ الصغير."},{"h":"الحذر من المبالغة","x":"كثيرًا ما تنطوي المبالغة على الكذب، كالشاب الذي صدم حين عرف أن أباه لم يكن صاحب المركز الحساس الذي تصفه أمه."},{"h":"الصدق قيمة عليا","x":"أن يشعر الطفل أن الصدق من القيم الإسلامية العليا، وأن نظهر له مقتنا للكذب، كالأم التي حفظت أكثر من عشرين قصة عن مصير الكذابين."}]},{"t":"الصدق يخفف العقوبة","pg":18,"key":"من المهم ألا نعطي الطفل انطباعًا بأن الكذب يُنجيه من العقوبة؛ بل علينا أن نقرر له بوضوح أن الصدق يخفف من عقوبة الخطأ الذي ارتكبه","p":["وأن إخفاء الخطأ الذي وقع فيه، يستوجب عقوبتين: عقوبة الخطأ وعقوبة الكذب في التنصل منه."],"items":[{"h":"معرفة الدافع الحقيقي","x":"إن كان الدافع الخوف خففنا العقوبة، وإن كان التقليد وقفنا مع أنفسنا وقفة صادقة، وإن كان الشعور بالنقص عززنا ثقته بنفسه."},{"h":"لا نرسخ أنه كذاب","x":"المطلوب أن نثني أمامه على الصادقين، ونشجع كل موقف صدق منه، ونشعره أن كذبته هفوة نأمل ألا تتكرر."}]}],"quiz":[{"q":"ما الذي يقرره الكتاب في أصل الكذب لدى الطفل؟","o":["صفة مكتسبة بالتعليم والتقليد","صفة فطرية تظهر مع نمو لغة الطفل","صفة وراثية تنتقل من الأبوين","صفة عارضة يمحوها الكبر وحده"],"why":"علينا في البداية أن نؤكد على أن الكذب ليس صفة فطرية أو وراثية لدى الطفل، أي إنها صفة مكتسبة تتكون لدى الطفل عن طريق التعليم والتقليد وتراكم الخبرة","pg":13},{"q":"وفق الدراسة التي ذكرها المؤلف، ما أكثر ما يرجع إليه كذب الأطفال؟","o":["الخوف من عقاب الكبار","أحلام اليقظة والخيال","أغراض الغش والخداع","تقليد الكبار في البيت"],"why":"وقد أشارت إحدى الدراسات إلى أن حوالي (70%) من أنواع السلوك لدى الأطفال الذين يتصفون بالكذب يرجع إلى الخوف من العقاب","pg":14},{"q":"طفل في الرابعة يحكي بثقة أنه رأى قطة لها قرون. كيف يُنظر إلى قوله بحسب الكتاب؟","o":["خيال طبيعي لا يقلق في هذه السن","كذب مبكر يستوجب عقوبة حازمة فورًا","علامة واضحة على ضعف ثقته بنفسه","تقليد لكذب سمعه من الكبار"],"why":"الكذب عند ابن أربع أو خمس سنوات، لا يشكل شيئًا مقلقًا؛ وذلك لأن الطفل في هذه المرحلة لا يستطيع التمييز بين الخيال والواقع","pg":16},{"q":"أخفى ابنك خطأ ثم انكشف أنه كذب في التنصل منه. ما الرسالة التي يوصي الكتاب بإيصالها؟","o":["الإخفاء يجلب عقوبتين لا عقوبة واحدة","الكذب يغفر إن اعتذر عنه سريعًا","العقوبة واحدة سواء صدق أم كذب","الاعتراف المتأخر يسقط العقوبة كلها"],"why":"وأن إخفاء الخطأ الذي وقع فيه، يستوجب عقوبتين: عقوبة الخطأ وعقوبة الكذب في التنصل منه.","pg":18},{"q":"ما الذي يحذر منه المؤلف بعد أن تتكرر كذبات الطفل؟","o":["أن نثبت في وعيه أنه كذاب","أن نثني أمامه على الصادقين","أن نخفف عقوبته إن صدق","أن نبحث عن دافعه الحقيقي"],"why":"الحذر ثم الحذر من أن نرسّخ في وعي الطفل أنه كذاب، وأننا نعرف كل الكذبات التي صدرت منه","pg":18}],"scene":{"t":"التحفة المكسورة","x":"انكسرت تحفة في البيت، وأنت شبه متأكد أن ابنك ابن الثامنة هو الفاعل، فلما سألته أنكر.","opts":["لا تحاصره ليعترف، وتقرر له بهدوء أن الصدق يخفف العقوبة","تواجهه أمام إخوته حتى يعترف بما فعل","تعاقبه فورًا عقوبة شديدة حتى لا يكذب ثانية"],"why":"حاول ألا تحشر الطفل في زاوية ضيقة، وتطلب منه الاعتراف بجرم ارتكبه أو خطأ وقع فيه","pg":16}},{"k":"c2","t":"ضعف الرغبة في الدراسة","q":"كيف نصنع في الطفل دافع التعلم؟","essence":"الرغبة في التعلم تصنعها الأسرة والمدرسة","kw":["الدافعية","الجو الأسري","المكافأة"],"sections":[{"t":"مشكلة كبرى للأسرة","pg":21,"key":"فإن عدم امتلاك الطفل لدافع قوي إلى تحصيل علمي جيد، هو عبارة عن مشكلة كبرى لأسرته","p":[],"items":[{"h":"لماذا الآن أكثر من قبل؟","x":"صار التزود بالمعارف والخبرات والمهارات المدخل الوحيد لرقي الأفراد والأسر والشعوب، ولهذا يهيب المؤلف بالآباء أن يكونوا كرماء في تعليم أبنائهم."}]},{"t":"ما المقصود بضعف الرغبة؟","pg":22,"key":"الدافع هو طاقة كامنة لدى الطفل تحركه في اتجاه سلوك معين","p":["لكن الأمنيات والأحلام تظل أقرب إلى الأوهام ما لم تتحول إلى رغبات مقلقة، وتتحول إلى دوافع محرِّكة"],"items":[{"h":"فتور بعد اندفاع","x":"نرى أطفالًا مندفعين إلى العلم في السنوات الأربع الأولى ثم تفتر عزائمهم وتنخفض درجاتهم؛ لأنهم فقدوا الطاقة التي تحملهم على بذل الجهد."}]},{"t":"مظاهر ضعف الرغبة","pg":23,"key":"رسوب الطفل في جميع المواد ورسوبه في مادتين فأكثر على نحو مكرر.","p":[],"items":[{"h":"التباطؤ في الواجبات","x":"لا يؤديها إلا بعد الإلحاح، ويظهر التبرم، ويؤدي بعضها ويترك الباقي."},{"h":"درجات متدنية","x":"الحصول على درجات متدنية في ثلاث مواد فأكثر."},{"h":"أعذار الغياب","x":"يتعلل يومًا بألم الضرس ويومًا بوجع المعدة أو بأن المدرس لن يحضر."},{"h":"ذكاء بلا شغف","x":"قد ينجح الذكي بتفوق دون تعلق بالكتاب، وهذه إشارة سلبية لأن الشغف بالتعلم شرط للتفوق الباهر."}]},{"t":"الأسرة تصنع الرغبة","pg":24,"key":"الجو الأسري المحفز على التعلم قد يكون أهم ما على الأسر توفيره لأطفالها","p":["فإن الرغبة في التعبد وعمل الخير وطلب العلم... تُصنع صناعة من قبل الأسرة، ويكتسبها الأطفال من أسرهم ومعلميهم"],"items":[{"h":"تجربة الأول على الثانوية","x":"شرح فتى أن إنجازه ثمرة جهود أبيه وأمه وأخته: أب يردد موعظة العلم ويضرب له مثلًا بقريبه الطبيب، وأسرة توفر المال، وأم تلغي زياراتها قبل اختباراته."},{"h":"الموقف عند الإخفاق","x":"حين رسب في الجغرافيا قال له أبوه إن الرسوب شيء عابر في حياته، وذكر له كبوات العلماء، فحماه من الإحباط ونجح."}]},{"t":"الأسباب الجسمية والمدرسة","pg":27,"key":"المدرسة الجيدة هي المدرسة التي يتوفر فيها شيئان أساسيان: جدية في التعليم، وشعور المدرسين فيها بالرضا عن أوضاعهم وأوضاع مدرستهم","p":["إن معالجة هذه المشكلات يعد شرطًا مهمًا لتقوية رغبة الطفل في التعلم ومواصلة الدراسة."],"items":[{"h":"البحث عن السبب","x":"على الأب ألا يكتفي بالحث على الجهد، بل يبحث عن سبب نفسي أو جسمي كضعف السمع أو الحاجة إلى نظارة أو بطء الفهم أو التأتأة أو الحياء الشديد."},{"h":"النظر من الداخل","x":"على الآباء أن ينظروا إلى المدارس من الداخل، وإلى الإنسان فيها أكثر من الأبنية والتجهيزات."},{"h":"التواصل مع المدرسة","x":"للمدارس علينا حق التواصل والمؤازرة والنصح، ومتابعة أحوال الأبناء مع المعلمين بانتظام."}]},{"t":"الثناء والمكافأة","pg":30,"key":"الطفل الصغير جدًا يحتاج إلى المكافأة المادية أكثر، وكلما كبر كبرت حاجته إلى المكافأة المعنوية","p":["كافئ، وشجّع وفكّر بصمت كيف تكون النتائج أفضل في المستقبل، وكيف يمكن مساعدة الطفل على الوصول إليها."],"items":[{"h":"المكافأة على الإنجاز والكف","x":"الثناء والتشجيع والمكافأة على الإنجاز وعلى الكف عن السلوك السلبي مما ينبغي أن يهتم به كل مرب، أبًا كان أم معلمًا."},{"h":"خطأ المعايير العالية","x":"الأب الذي يوبخ ابنه لحصوله على المركز الثالث لأنه توقع الأول يتبع أسلوبًا خاطئًا قد يورث الإحباط والعجز."}]}],"quiz":[{"q":"بم يعرّف المؤلف الدافع؟","o":["طاقة كامنة تحرك الطفل نحو سلوك معين","أمنية يحملها الطفل للتفوق والبروز","رغبة عابرة تثيرها المكافأة المادية وحدها","ذكاء فطري يدفع الطفل إلى المطالعة"],"why":"الدافع هو طاقة كامنة لدى الطفل تحركه في اتجاه سلوك معين","pg":22},{"q":"طالب ذكي ينجح بتفوق دون أي تعلق بالكتاب أو المطالعة. كيف يقرأ الكتاب حاله؟","o":["إشارة سلبية، فالشغف شرط للتفوق الباهر","حالة مطمئنة ما دامت درجاته مرتفعة دائمًا","علامة على ضعف السمع أو بطء الفهم","دليل على أن مدرسته جادة في التعليم"],"why":"وهذا الأمر لا يزعج الأهل في العادة لكنه يرسل بإشارات سلبية؛ حيث إن الشغف بالتعلم والحصول على المعارف شرطٌ للتفوق الباهر.","pg":24},{"q":"وجد أب أن تحصيل ابنه ضعيف مقارنة بزملائه. بم يوصيه الكتاب؟","o":["أن يبحث عن سبب نفسي أو جسمي وراءه","أن يكتفي بحثه على مضاعفة الجهد","أن ينقله فورًا إلى مدرسة أهلية","أن يقارنه بزملائه ليثير فيه المنافسة"],"why":"فإن عليه ألا يكتفي بحثّه على بذل المزيد من الجهد؛ بل عليه أن يبحث فيما إذا كان ذلك لسبب نفسي أو جسمي","pg":26},{"q":"ما الشيئان اللذان تكون بهما المدرسة جيدة في نظر المؤلف؟","o":["جدية التعليم ورضا المدرسين عن أوضاعهم","فخامة المباني وكثرة التجهيزات الحديثة","ارتفاع الرسوم وقلة عدد الطلاب فيها","شهرة المدرسة وكثرة المتفوقين فيها"],"why":"المدرسة الجيدة هي المدرسة التي يتوفر فيها شيئان أساسيان: جدية في التعليم، وشعور المدرسين فيها بالرضا عن أوضاعهم وأوضاع مدرستهم","pg":27},{"q":"حصل ابن على المركز الثالث فوبخه أبوه لأنه كان يتوقع الأول. كيف يصف الكتاب هذا التصرف؟","o":["أسلوب خاطئ قد يورث الإحباط والعجز","حزم مطلوب لرفع سقف الطموح لديه","معيار عال يصنع التفوق الباهر","تحفيز معنوي يناسب سن المراهقة"],"why":"وهذا أسلوب خاطئ في التربية، ونتيجته قد تكون شعور الطفل بالإحباط والعجز","pg":30}],"scene":{"t":"شهادة آخر الفصل","x":"عاد ابنك بشهادة فيها تحسن واضح، لكنه لم يبلغ الدرجة التي كنت تتمناها له.","opts":["تكافئه وتشجعه، ثم تفكر بصمت في طريق تحسين النتائج","تؤجل أي تهنئة حتى يبلغ الدرجة التي تريدها","تذكره بتفوق ابن عمه ليحفزه على المنافسة"],"why":"كافئ، وشجّع وفكّر بصمت كيف تكون النتائج أفضل في المستقبل، وكيف يمكن مساعدة الطفل على الوصول إليها.","pg":30}},{"k":"c3","t":"النشاط الحركي الزائد","q":"متى تصبح حركة الطفل مشكلة، وكيف نتعامل معها؟","essence":"الصبر والثناء أساس علاج فرط الحركة","kw":["فرط الحركة","تشتت الانتباه","الاتفاقية"],"sections":[{"t":"حدود المشكلة","pg":31,"key":"النشاط الزائد هو حركات جسمية تفوق الحد الطبيعي أو المعتاد","p":["نصائح وفتاوى تربوية لا تزيد الأهل إلا حيرةً وارتباكًا!"],"items":[{"h":"المقارنة وسيلة للتشخيص","x":"على الأب أن يزور مدرسة ابنه وقت الفسحة أو يراه مع أولاد الأقارب والجيران، فإذا رأى فرقًا واضحًا في كثرة الحركة والنشاط غير الهادف فهذا دليل أولي على وجود مشكلة."}]},{"t":"علامات فرط الحركة","pg":32,"key":"ولا بد من أن يكون ضعف القدرة على التركيز وتشتت الانتباه ظاهرًا في سلوك الطفل في البيئة الاجتماعية (المنزل) وفي البيئة الأكاديمية (المدرسة) معًا، وإلا كان العيب في البيئة نفسها وليس في الطفل.","p":[],"items":[{"h":"صعوبة الاستقرار","x":"لا يستقر في مكان مدة طويلة، ويفشل في إتمام المهمات، ويكثر من تسلق الجدران والأماكن المرتفعة."},{"h":"الاندفاع والنسيان","x":"يزداد نشاطه مع المؤثرات الصوتية والمرئية، وينسى سريعًا، ويتصرف دون التفكير في العواقب."},{"h":"عدم القناعة","x":"لا يقبل بأي شيء، ويستمر في السؤال عن الموضوع نفسه، ويتدخل في شؤون الآخرين."},{"h":"الملل من ألعاب التركيز","x":"يمل الألعاب التي تستدعي تركيزًا ذهنيًا ويقبل على الألعاب المحسوسة."},{"h":"الانتشار كما يورده المؤلف","x":"أكثر بين الذكور ولدى الأسر الفقيرة، ويظهر بين 5 و9 سنوات، وقد يستمر أكثر من 30% من الحالات إلى الشباب."}]},{"t":"بيئة أسرية واقية","pg":34,"key":"لا يصح أن يكون عمل الأسر هو إطفاء الحرائق على نحو مستمر، وإنما المطلوب دائمًا توفير بيئة تساعد الصغار على أن يكونوا أصحاء نفسيًا وجسديًا","p":["وقد ثبت أن مناكفة الأهل للطفل لا تخفف من حركته، بل تزيدها"],"items":[{"h":"حماية الأم أثناء الحمل","x":"البعد عن القلق والتوتر الشديد والتدخين وبعض العقاقير مما يقي الطفل."},{"h":"المسكن الهادئ","x":"المسكن الجيد هادئ وجميل ومنظم، وتوفر الألعاب المتنوعة يقلل لجوء الطفل إلى كثرة الحركة."},{"h":"هدوء الأبوين","x":"الطفل يقلد أبويه، فهدوؤهما والتزامهما بإنهاء مهماتهما وشرحهما لذلك يساعده على التركيز، كالأب الذي يعلن أنه سيجلس أربعين دقيقة حتى ينهي كتابه."}]},{"t":"التعامل مع الطفل المصاب","pg":37,"key":"المطلوب هو أن ندرك أننا نتعامل مع مريض وليس مع شخص سويّ","p":["بل إن الصبر والاهتمام، هما أساس معالجة الطفل الذي يعاني من المشكلة التي نحن بصددها."],"items":[{"h":"ترك الخطاب السلبي","x":"التوبيخ واللوم والنهي المستمر والضرب تجعل الطفل ذليلًا مكتئبًا أو متمردًا معارضًا."},{"h":"الثناء بدل اللوم","x":"أم متخصصة في التعليم المبكر كانت تقبل ابنها إذا استقر خمس دقائق، وتعطيه حلوى أو نقودًا إذا أنهى واجباته في جلسة واحدة."},{"h":"شروط مقابل ما يحب","x":"سمحت له بزيارة ابن الجيران عشرين دقيقة بثلاثة شروط: ألا يلح، وأن ينهي واجباته، وأن يجلس هادئًا على العشاء."}]},{"t":"الاتفاقية بعد التاسعة","pg":39,"key":"حين يتجاوز الطفل المصاب التاسعة، فإن أسلوب التعامل معه يحتاج إلى شيء من التطوير","p":["وتنبع أهمية مثل هذه الاتفاقية من كونها تنظِّم وعي الأبوين تجاه ما عليهما القيام به نحو طفلهما، كما تنظم وعي الطفل تجاه ما هو مطلوب منه."],"items":[{"h":"نموذج اتفاقية","x":"ابن يلتزم بالهدوء في المدرسة وأداء الواجبات وترتيب فراشه والاستيقاظ للفجر، والأب يلتزم بدراجة بعد شهر وزيادة المصروف بعد شهرين، ويوقع الطرفان."}]}],"quiz":[{"q":"متى يعد ضعف التركيز علامة على فرط الحركة لا على خلل في البيئة؟","o":["إذا ظهر في المنزل والمدرسة معًا","إذا ظهر في المدرسة دون المنزل","إذا ظهر أمام الضيوف والأقارب","إذا ظهر في ألعاب الحركة وحدها"],"why":"ولا بد من أن يكون ضعف القدرة على التركيز وتشتت الانتباه ظاهرًا في سلوك الطفل في البيئة الاجتماعية (المنزل) وفي البيئة الأكاديمية (المدرسة) معًا، وإلا كان العيب في البيئة نفسها وليس في الطفل.","pg":32},{"q":"كيف يتحقق الأب الذي ليس لديه سوى ولد واحد من وجود المشكلة لديه؟","o":["بمقارنته بأقرانه في المدرسة وأماكن اللعب","بسؤال الضيوف والأقارب عن رأيهم فيه","بملاحظته منفردًا في غرفته مدة طويلة كل يوم","بانتظار سنوات حتى يزول ما به وحده"],"why":"فإذا رأى فرقًا واضحًا بين ابنه وبين غيره من الأطفال في كثرة الحركة وفي كثرة النشاط غير الهادف، فهذا دليل أوّلي على وجود مشكلة.","pg":32},{"q":"ما أثر مناكفة الأهل للطفل كثير الحركة كما يذكره الكتاب؟","o":["تزيد حركته ولا تخففها","تخفف حركته مع الوقت","تعلمه الانضباط سريعًا","لا أثر لها في سلوكه"],"why":"وقد ثبت أن مناكفة الأهل للطفل لا تخفف من حركته، بل تزيدها","pg":35},{"q":"ما المنطلق الذي يراه المؤلف للتعامل مع الطفل المصاب بفرط الحركة؟","o":["معاملة المريض بالصبر والاهتمام","معاملة السوي بالحزم والمحاسبة","معاملة الكبير بالنقاش الطويل","معاملة العنيد بالتجاهل التام"],"why":"المطلوب هو أن ندرك أننا نتعامل مع مريض وليس مع شخص سويّ","pg":37},{"q":"تجاوز ابنك المصاب التاسعة. ما الأسلوب الذي يضيفه الكتاب في هذه المرحلة؟","o":["عقد اتفاق يوقعه الطفل وأبوه","زيادة التوبيخ ليتحمل المسؤولية","منعه من اللعب حتى يهدأ تمامًا","الاكتفاء بالثناء كما في صغره"],"why":"إلا أنه يمكن إجراء عقد أو اتفاقية مع الطفل","pg":39}],"scene":{"t":"هدوء نادر","x":"طفلك كثير الحركة جلس هادئًا بضع دقائق بين الضيوف على غير عادته.","opts":["تقترب منه وتثني عليه وتقبله على هدوئه","تتركه دون تعليق حتى لا يعود إلى الحركة","تذكره بأن عليه أن يبقى هكذا دائمًا"],"why":"من الملائم دائمًا أن نبحث عن فرصة للثناء على الطفل ليكون بديلًا عن اللوم والتقريع","pg":37},"rel":[{"b":"ten","ci":8,"t":"القاعدة التاسعة: تفهم أسباب مشكلاتهم"}]},{"k":"c4","t":"الشجار بين الأبناء","q":"متى يصبح شجار الإخوة مقلقًا، وكيف نخففه؟","essence":"العدل ووضوح النظام يطفئان شجار الإخوة","kw":["العدل","الخصوصية","الموارد المحدودة"],"sections":[{"t":"شجار مألوف وشجار مقلق","pg":42,"key":"فإن خلوّ المنزل من أي شكل من أشكال الصراع، لا يرسل رسالة إيجابية على نحو كامل.","p":["فهم يكتشفون قدراتهم على التغلب على الغير، ويَخْبرون مشاعر التسامح والنصر وتقبل الهزيمة، كما يكتشفون نقاط ضعفهم"],"items":[{"h":"متى يصبح مشكلة؟","x":"إذا تطور إلى عراك بالأيدي أو آلات حادة، أو استخدم فيه الكلام البذيء، أو تكرر على نحو غير مألوف، أو أشغل الأولاد عن واجباتهم."},{"h":"القهر والانتقام","x":"إذا شعر أحدهم بالقهر من ظلم أخيه، ولا سيما الأصغر، أو تعاظمت لديه الرغبة في الانتقام، صار تدخل الأهل ضروريًا."}]},{"t":"لماذا يتشاجر الإخوة؟","pg":44,"key":"وكلما كانت هذه الأشياء قليلة وشحيحة زادت حدة المنافسة وزاد الشجار بين الأطفال، والعكس صحيح.","p":[],"items":[{"h":"الموارد المحدودة","x":"محبة الوالدين ورعايتهما، والمكان، والألعاب والأدوات."},{"h":"تعارض الرغبات","x":"ثلاثة أولاد في غرفة واحدة: هذا يريد النوم وذاك يريد إكمال واجبه، ومقعد السيارة بجانب الأب."},{"h":"الإهمال والطاقة الزائدة","x":"الطفل المهمل يفتعل المشكلات ليلفت الأنظار، والطفل ذو الطاقة الزائدة قد يعتدي على إخوته."},{"h":"التفضيل والمقارنة","x":"تفضيل أحد الأبناء يغلي صدر أخيه بالحقد كما في قصة يوسف عليه السلام، والمقارنة السلبية تشعر الضعيف بالظلم."},{"h":"نزاع الوالدين والقسوة وسوء الفهم","x":"النزاع بين الوالدين يجعل جو المنزل متوترًا، والقسوة تضعف التعاطف، والطفل كثيرًا ما يفسر كلام إخوته تفسيرًا خاطئًا."}]},{"t":"قبل العلاج","pg":47,"key":"تعالوا لننظر إلى الشجار الخطِر والمؤذي بين أطفالنا على أنه أحد أعراض الخلل في تربيتنا لهم","p":["إن المبالغة في صياغة العلاقة بين الأبناء والمبالغة في التدخل بينهم ليست بالشيء الجيد؛ وذلك لأننا نريد لهم أن يتدربوا على حل مشكلاتهم بأنفسهم قدر الإمكان"],"items":[{"h":"الاستعداد لبذل الجهد","x":"التربية الصالحة تحتاج إلى صبر على تكاليفها؛ فالسمو مكلف والانحدار سهل."}]},{"t":"العدل بين الأبناء","pg":51,"key":"العدل بين الأبناء لا يعني المساواة، ولكنه يعني إعطاء كل واحد منهم ما يحتاجه بالمعروف","p":[],"items":[{"h":"الأساس النبوي","x":"في حديث النعمان بن بشير قال النبي صلى الله عليه وسلم: «فاتقوا الله واعدلوا بين أولادكم»، وذهب بعض أهل العلم إلى العدل حتى في التقبيل."},{"h":"لا نموذج على حساب أخيه","x":"شاب كان أبوه يطلب منه تقليد أخيه الأكبر في كل شيء فآذاه ذلك وجرحه."},{"h":"الحذر من التدليع والتحقير","x":"لا يخص أحدهم بألفاظ التحبب ويقسو على الآخر، ولا يقلل شأن أحدهم كالأب الذي قال لأحد أبنائه إنه لن يكون مؤهلًا لشيء."},{"h":"العدل في الوقت","x":"لا يصطحب أحدهم دائمًا في الزيارات والسوق ويحرم البقية."},{"h":"سؤال الأبناء","x":"لا يعتمد الأبوان على حدسهما، بل يسألان الأبناء بين الفينة والفينة إن كانوا يشعرون بمعاملة غير عادلة."}]},{"t":"تنظيم الحياة المشتركة","pg":53,"key":"فتفويض الكبير بالإشراف على إخوته الصغار يجب أن يكون جزئيًا، ويجب أن يظل الوالدان في الصورة حتى لا يقع في أخطاء فادحة","p":[],"items":[{"h":"احترام الخصوصيات","x":"يقدم الأبوان النموذج الحي في احترام الخصوصية والملكية الخاصة، ويعلمان: هذه لعبة فلان وليست لعبتك."},{"h":"المرح والأنشطة الجماعية","x":"الأسر المحرومة من المرح والخروج يورثها الملل، فيجد الطفل في مناكفة أخيه متنفسًا."},{"h":"وضوح المسؤوليات","x":"توزيع واضح عادل للمهام بنظام تبادلي، وتحديد وقت لاستخدام الهاتف والألعاب المشتركة."},{"h":"غض الطرف عن الصغائر","x":"ينبغي عدم الالتفات إلى الخلافات الصغيرة، وعدم الاستماع إلى الوشايات حولها."}]},{"t":"حدود لا يتجاوزها الشجار","pg":54,"key":"من المهم أن يكون الأب واضحًا في أنه لن يسمح للشجار بأن يتجاوز حدود الكلام المهذب","p":["كل كلمة لا تجد أن من المناسب التحدث بها مع شخص غريب، فلا تتحدث بها مع أخيك"],"items":[{"h":"تعليم المشاركة","x":"يعلم الآباء أبناءهم كيف يتداولون اللعبة الواحدة ويقولون: إذا اختلفتم بعد اليوم، فسوف نمنعكم من كل ذلك حتى تتفقوا."},{"h":"العقوبة على التجاوز","x":"الضرب والشتم وإطلاق الألقاب السيئة وتعمد الإغاظة أمور سينال صاحبها عليها العقوبة."}]}],"quiz":[{"q":"ما موقف المؤلف من بيت يخلو تمامًا من أي شجار بين الأبناء؟","o":["لا يرسل رسالة إيجابية على نحو كامل","هو البيت المثالي الذي ينشده المربون","دليل على عدل الأبوين بين الأبناء","علامة على قوة شخصية الأب وحزمه"],"why":"فإن خلوّ المنزل من أي شكل من أشكال الصراع، لا يرسل رسالة إيجابية على نحو كامل.","pg":42},{"q":"في أي الحالات الآتية يصبح تدخل الأهل في شجار الإخوة ضروريًا؟","o":["حين يشعر الأصغر بالقهر من ظلم أخيه","حين يختلفان مرة على برنامج تلفازي","حين يتنافسان في لعبة جماعية هادئة","حين يتجادلان في مسألة مدرسية بأدب"],"why":"شعور أحد الأولاد المتشاجرين بالقهر بسبب ظلم أخيه له، ويتأكد هذا إذا كان المقهور هو الأصغر.","pg":43},{"q":"ما المقصود بالعدل بين الأبناء كما يحدده الكتاب؟","o":["إعطاء كل واحد ما يحتاجه بالمعروف","تقسيم كل شيء بينهم بالتساوي التام","تقديم المتفوق نموذجًا لبقية إخوته","منح الأكبر سلطة كاملة على الأصغر"],"why":"العدل بين الأبناء لا يعني المساواة، ولكنه يعني إعطاء كل واحد منهم ما يحتاجه بالمعروف","pg":51},{"q":"يكثر ابنك الشكوى من أخيه في أمور صغيرة لم تقع غالبًا. ماذا يقترح الكتاب؟","o":["ألا تلتفت إلى هذه الوشايات الصغيرة","أن تعاقب المتهم فور سماع الشكوى","أن تكلف الأكبر بالفصل بينهما دائمًا","أن تجمعهما للتحقيق في كل شكوى"],"why":"فينبغي دائمًا عدم الالتفات إلى الخلافات والنزاعات الصغيرة، وعدم الاستماع إلى الوشايات حولها","pg":53},{"q":"ما القاعدة التي كان أحد الآباء يضعها لأولاده في حدود الكلام بين الإخوة؟","o":["ما لا يقال لغريب لا يقال لأخيك","من بدأ الشجار يعاقب وحده دائمًا","الكبير يعتذر أولًا مهما كان الأمر","لا كلام بينكما حتى يهدأ الغضب"],"why":"كل كلمة لا تجد أن من المناسب التحدث بها مع شخص غريب، فلا تتحدث بها مع أخيك","pg":54}],"scene":{"t":"مقعد السيارة","x":"في كل رحلة يتشاجر أبناؤك على من يجلس بجانبك في السيارة، ولا تعرف من المحق.","opts":["تضع نظامًا تبادليًا واضحًا يعرف به كل واحد دوره","تجلس الأكبر دائمًا لأنه أحق بالمكان","ترفع صوتك عليهم جميعًا حتى يسكتوا ثم تمضي"],"why":"الغموض في المسؤوليات والواجبات والأشياء كثيرًا ما يؤجِّج الخلاف بين الأبناء","pg":52}},{"k":"c5","t":"الشعور بالدونية","q":"كيف تتكون صورة الطفل السلبية عن نفسه، وكيف نصححها؟","essence":"صورة الطفل عن نفسه تصنع ويعاد بناؤها","kw":["الثقة بالنفس","الحب غير المشروط","حديث النفس"],"sections":[{"t":"ما الشعور بالدونية؟","pg":57,"key":"إن الشعور بالدونية هو مجموعة الصور السلبية التي يختزنها الطفل في ذاكرته عن ذاته","p":[],"items":[{"h":"مقياس المقارنة","x":"يشعر الطفل بالدونية حين يقيس نفسه على من هم في مثل سنه فيجد النتيجة ليست في مصلحته، كمن يرفض زملاؤه ضمه إلى اللعب أو يتكرر رسوبه."},{"h":"الخضوع لكلام الآخرين","x":"معرفة الإنسان بذاته نسبية، والصغار أكثر خضوعًا لما يقوله الآخرون عنهم من الكبار."}]},{"t":"مظاهر الشعور بالدونية","pg":59,"key":"والسبب وراء كل ذلك هو الشعور بنقص الكفاءة والقدرة على مواجهة ظروف لا عهد له بها","p":[],"items":[{"h":"الخوف من أمور عديدة","x":"يخاف الخوض في الماء أو المشي في الظلام أو الدفاع عن نفسه أو دخول مسابقة."},{"h":"التشاؤم","x":"لا يرى الإمكانات المتاحة، وينسب نجاحات غيره إلى مواهب لا يملكها، كالطفل الذي ضعف حين انهار حلمه بأن يكون طيارًا بسبب قصر قامته."},{"h":"تحديث النفس بالضعف","x":"يردد: أنا سيئ، أنا غبي، أنا لا أصلح لشيء، فتترسخ قناعته."},{"h":"فقد الحماسة","x":"يفقد حماسته بسرعة، وينسحب عند أول عقبة يصادفها."}]},{"t":"أسباب الشعور بالدونية","pg":61,"key":"والتغلب على ذلك دائمًا ممكن لكن من خلال العناية الفائقة والتدريب الجيد.","p":[],"items":[{"h":"الوراثة والعاهات","x":"بعض الأطفال يرثون الاستعداد، ونقص الذكاء أو العاهة ينعكس على الثقة."},{"h":"التوقعات المبالغ فيها","x":"أب يريد من ابنه أن يحقق أحلامه التي عجز عنها، فيشعر الابن بالعجز ويستسلم."},{"h":"المبالغة في الحماية","x":"يظن الآباء أنهم يحسنون، ولا ينتبهون إلى أنهم يحرمون أبناءهم الاستقلالية وخبرة التعامل مع المشكلات."},{"h":"القسوة والتسلط","x":"بعض الآباء حولوا بيوتهم إلى ما يشبه الثكنات العسكرية بالصرامة والنقد المستمر."},{"h":"تقليد الكبار","x":"الأب ضعيف الثقة الكثير الشكوى والتردد يقلده ابنه في مقولاته ومواقفه."}]},{"t":"التفكير المنطقي المتوازن","pg":64,"key":"الاعتراف من الجميع بأن النقص ملازم لبني البشر","p":["المحاولة المستمرة والمضي في الطريق الصحيح هما ركنا النجاح، أما النتائج فهي محكومة باعتبارات عديدة"],"items":[{"h":"حديث الأبوين عن ضعفهما","x":"جميل أن يتحدث الأب عن المواد التي كان ضعيفًا فيها، فهذا يخفف عن الطفل ضغط الشعور باختلافه."},{"h":"نقاط القوة والضعف","x":"طالب ضعيف الحفظ أراد أبوه إخراجه من المدرسة، فأبرز معلمه موهبته في الحساب، فصار طالبًا في كلية الهندسة."},{"h":"لا ثقة مطلقة","x":"الإنسان يشعر تارة بالقوة وتارة بالضعف، ومناقشة ذلك في الأسرة ترفع معنويات الطفل."},{"h":"معنى النجاح","x":"النجاح الحقيقي في بذل أقصى الجهد والعمل بطريقة صحيحة ثم الرضا بما قسم الله."}]},{"t":"حماية معتدلة وتقبل الأسرة","pg":67,"key":"الأسلوب الصحيح الذي ينبغي اتباعه في هذا الشأن هو: ترك الطفل يعالج مشكلاته بنفسه، ويستخدم كل الأساليب الممكنة في ذلك، وإذا احتاج إلى مساعدة قدّمناها له.","p":["أسرة الطفل هي المرآة التي يرى فيها نفسه"],"items":[{"h":"جائزة صاحب الحل","x":"أب كان يطلب من طفليه المتشاجرين أن يبحثا عن حل، ويعطي الجائزة لصاحب الحل الأفضل، فخفت مشاجراتهما بعد سنتين."},{"h":"رسائل الترحيب","x":"إرسال رسائل للطفل بأن أبويه سعيدان بوجوده، بالكلمات والتقبيل والاحتضان."},{"h":"التعاطف عند الإخفاق","x":"حين يخفق نقف إلى جانبه ونقول: كثيرون أخفقوا ثم عوضوا بنجاحات عظيمة."},{"h":"الجو الدافئ","x":"ترك الإكثار من نقد الآخرين، وذكر قصص النجاح، وإشاعة الدفء والسرور في الأسرة."}]},{"t":"حديث النفس الإيجابي","pg":70,"key":"إن هذه العبارات وأشباهها تترك آثارًا كبيرة في نفسية الطفل","p":[],"items":[{"h":"عبارات الثقة","x":"نعلمه أن يردد مثل: «أنا في خير من الله وأشعر بالسعادة»، ونشرح له معناها ونساعده على ضرب الأمثلة."},{"h":"الأنشطة والمسؤوليات","x":"الزج به في جمعيات ثقافية وفرق كشفية وأنشطة رياضية وحلقات تحفيظ القرآن، وتكليفه بمسؤوليات في المنزل."}]}],"quiz":[{"q":"كيف يعرّف المؤلف الشعور بالدونية؟","o":["صور سلبية يختزنها الطفل عن ذاته","خوف فطري يولد مع الطفل ويلازمه","ضعف في الذكاء يظهر في الدراسة","حياء ممدوح يمنعه من محادثة الكبار"],"why":"إن الشعور بالدونية هو مجموعة الصور السلبية التي يختزنها الطفل في ذاكرته عن ذاته","pg":57},{"q":"طفل يرفض دخول أي مسابقة ويخاف السباحة والمشي في الظلام. إلام يرجع الكتاب ذلك؟","o":["شعوره بنقص الكفاءة في ظروف جديدة","عناده ورفضه الأوامر الصادرة إليه","فرط حركته وتشتت انتباهه الدائم","أنانيته وحبه الاستحواذ على الأشياء"],"why":"والسبب وراء كل ذلك هو الشعور بنقص الكفاءة والقدرة على مواجهة ظروف لا عهد له بها","pg":59},{"q":"أي الأساليب الآتية يعدها الكتاب من أسباب الدونية مع أن أصحابها يظنونها إحسانًا؟","o":["المبالغة في العناية والتدليل","تكليف الطفل بمسؤوليات منزلية","إشراكه في الأنشطة الكشفية","تركه يحاول حل مشكلاته بنفسه"],"why":"يبالغ بعض الآباء في العناية بأبنائهم وفي تدليلهم وعدم تكليفهم بتقديم أي شيء للأسرة، وهم يظنون أنهم بذلك يُحسنون إليهم","pg":62},{"q":"واجه ابنك مشكلة صغيرة مع زميله. ما الأسلوب الذي يراه الكتاب صحيحًا؟","o":["أن يعالجها بنفسه ونساعده عند الحاجة","أن نحلها فورًا نيابة عنه دائمًا","أن نتجاهل الأمر كله ولا نسأله عنه","أن نعاقبه حتى لا يدخل في مشكلات"],"why":"الأسلوب الصحيح الذي ينبغي اتباعه في هذا الشأن هو: ترك الطفل يعالج مشكلاته بنفسه، ويستخدم كل الأساليب الممكنة في ذلك، وإذا احتاج إلى مساعدة قدّمناها له.","pg":67},{"q":"أخفق ابنك في اختبار مهم. ما الذي يمثل الحب غير المشروط كما يشرحه الكتاب؟","o":["أن نتعاطف معه ونقف إلى جانبه","أن نؤجل محبتنا حتى ينجح ثانية","أن نقارنه بمن نجح ليجتهد أكثر","أن نخفي عنه نتيجته حفاظًا عليه"],"why":"فينبغي أن نتعاطف معه، ونقف إلى جانبه، وهذا هو المعنى العميق للحب غير المشروط","pg":68}],"scene":{"t":"أنا لا أصلح لشيء","x":"ابنك يتعثر في حفظ النصوص حتى القصيرة منها، لكنه بارع في الحساب، وبدأ يقول: أنا لا أصلح لشيء.","opts":["تبرز له موهبته في الحساب وتعالج ضعف الحفظ برفق","تقرر أنه لا يصلح للدراسة وتوجهه إلى العمل","تضاعف ساعات الحفظ عليه حتى يتغلب على ضعفه"],"why":"لدى كل إنسان نقاط قوة ونقاط ضعف؛ ومن ثم فإن من المهم للأبوين أن يتحسَّسا نقاط الضعف والقوة لدى أولادهم","pg":64}},{"k":"c6","t":"العدوانية","q":"ما صور عدوان الطفل وأسبابه، وكيف نهذبه؟","essence":"بيئة آمنة ومكافأة السلم تهذبان العدوان","kw":["العدوان الرمزي","التجاهل","التسامح"],"sections":[{"t":"معنى العدوانية وصورها","pg":74,"key":"إن الطفل حين تُشبَع حاجاته بطريقة جيدة، ويعيش في أسرة جيدة وهادئة، فإن من المتوقع له أن يكون أكثر انضباطًا وأكثر احترامًا لحقوق الآخرين وأكثر مراعاة لمشاعرهم","p":[],"items":[{"h":"العدوان الجسدي","x":"إيذاء جسد طفل آخر أو شخص راشد بالضرب أو الخمش أو العض أو الرفس أو الدفع، وقد يصل إلى الأدوات الحادة."},{"h":"العدوان الكلامي","x":"الشتم والقذف والوصف بأوصاف مهينة، والصراخ والتهديد، وقد نقلت أم أسرتها من حي يسمع فيه أبناؤها الكلمات النابية."},{"h":"التخريب","x":"كسر الأواني وبعثرة ما رتبته الأم، وقد يصل إلى إيذاء النفس أو الحيوانات الأليفة."}]},{"t":"العدوان الرمزي","pg":76,"key":"إنه ذلك النوع من العدوان الذي لا تُستخدَم فيه اليد ولا اللسان، لكن يستخدم فيه النظر، ويظهر في المواقف","p":["وهذا اللون من العدوان شديد الأذى، وآثاره قد تكون أشد من أذى الضرب"],"items":[{"h":"صوره","x":"الإعراض عن السلام على طفل آخر أو مجالسته، والنظر إليه باحتقار، ونقل الكلام المسيء، بدافع الكبر والاستعلاء."},{"h":"مصدره","x":"كثيرًا ما يعكس مشاعر الأسرة التي نشأ فيها الطفل."}]},{"t":"لماذا يصبح الطفل عدوانيًا؟","pg":77,"key":"التعامل مع الطفل بقسوة، وتقليل مساحة الاختيار أمامه، وحرمانه من أمور عزيزة عليه... كل هذه الأمور مما ينمي روح الانتقام لدى الطفل","p":[],"items":[{"h":"ضيق المنزل","x":"ضيق المساحة وعدم وجود متنفس في الخارج يزيدان العدوانية."},{"h":"التخلص من الشعور بالنقص","x":"يثبت لمن حوله أنه قادر على إثارة الانتباه وكأنه يقول: أنا هنا، ويجب أن تحسبوا حسابي."},{"h":"ضيق مساحة التعبير","x":"الأسلوب التسلطي يمنع الطفل من التعبير عن ذاته فيعبر بالإيذاء والتخريب."},{"h":"إهمال الأهل وتشجيعهم","x":"يحدث كثيرًا في الأسر التي لم ترزق إلا بطفل واحد أو بذكر واحد، أو حين يأمر الأب ابنه أن يأخذ حقه بيده."},{"h":"التقليد والمشاهد العنيفة","x":"من يرى أباه يعتدي على أمه يظن العدوان طبيعيًا، وأفلام الرعب والأعمال العنيفة تشجعه."}]},{"t":"متى نقلق؟","pg":80,"key":"فإذا بلغ الطفل العاشرة، وظلت العدوانية واضحة في سلوكه، فإن على الأهل أن يولوا ذلك اهتمامًا خاصًا خشية تأصل هذا المرض في شخصيته","p":[],"items":[{"h":"مسار النمو","x":"تبدأ العدوانية بالظهور في سن الثالثة، ويميل الطفل في الرابعة إلى المجاملة، وفي الثامنة أو التاسعة يصبح انضباطه جيدًا."},{"h":"نسبة يوردها المؤلف","x":"تشير بعض الدراسات بحسبه إلى أن نحو 10% من الأطفال في سن العاشرة لديهم درجة من العدوانية."}]},{"t":"بيئة أمان وسلام","pg":81,"key":"فقد صار واضحًا أن أفضل طريقة لجعل الطفل لطيفًا ومهذبًا هو أن نعامله بلطف وتهذيب واحترام.","p":["وإن التدليل المفرط مثل الإفراط في الضبط والقسوة في التأديب، كلاهما يؤدي إلى تقوية النزعة العدوانية لدى الطفل."],"items":[{"h":"حجبه عن العنف المرئي","x":"صار التلفاز من المصادر الأساسية لتعليم العنف، فمن المهم مراقبة ما يشاهده الصغار."},{"h":"علاقة حسنة بين الأبوين","x":"تكون الخلافات عند حدها الأدنى حتى لا يتعلم الصغار الجدل العقيم وإيقاع الأذى."},{"h":"تفريغ الطاقة","x":"تخصيص مكان للعب في المنزل، وإتاحة اللعب في الحدائق والنوادي الآمنة."}]},{"t":"تعزيز السلم والتجاهل والتسامح","pg":83,"key":"إن من المهم أن يترصد الأبوان لطفلهما العدواني حتى يمسكاه وهو متلبس بسلوك جيد وهادئ ليقدما له الثناء والتشجيع والمكافأة.","p":["إننا لن نستطيع فهم مشاعر الناس يا بني، ولن نستطيع إنصافهم إلا إذا تخيلنا أنفسنا في نفس المواقف والظروف التي هم فيها."],"items":[{"h":"المكافأة على السلم","x":"أب وعد ابنه ببطاقة للألعاب إن لعب عشرين دقيقة بلا شجار، وآخر أعطى نجمة عن كل يوم بلا شكوى ودراجة عند خمسين نجمة."},{"h":"التجاهل","x":"تجاهل تصرفاته العدوانية يقللها لأنه قد يعتدي ليلفت الأنظار، مع الاهتمام بالطفل المعتدى عليه ومواساته."},{"h":"التعبير عن الحاجات","x":"على صاحب الحق أن يطالب بحقه بأسلوب مهذب، فإن أخذ زميل قلمه قال له بهدوء وعزيمة إنه له وعليه أن يرجعه."},{"h":"تنمية التسامح","x":"الحديث عن سعة رحمة الله، وتخيل موقف الآخر، وتوضيح أن في الحياة ظالمين ومظلومين، والرفق بالحيوان كما في حديث الهرة والكلب."}]}],"quiz":[{"q":"طفل يعرض عن السلام على زميله وينظر إليه نظرة احتقار. أي أنواع العدوان هذا؟","o":["العدوان الرمزي","العدوان الكلامي","العدوان الجسدي","التخريب للأشياء"],"why":"إنه ذلك النوع من العدوان الذي لا تُستخدَم فيه اليد ولا اللسان، لكن يستخدم فيه النظر، ويظهر في المواقف","pg":76},{"q":"ما الذي يقوله الكتاب عن أثر العدوان الذي يكون بالنظر والإعراض؟","o":["قد يكون أشد من أذى الضرب","أخف أنواع العدوان وأقلها ضررًا","يزول سريعًا دون أي علاج","لا يظهر إلا في الأسر الفقيرة"],"why":"وهذا اللون من العدوان شديد الأذى، وآثاره قد تكون أشد من أذى الضرب","pg":76},{"q":"متى يرى المؤلف أن استمرار العدوانية يستوجب اهتمامًا خاصًا من الأهل؟","o":["إذا بلغ الطفل العاشرة","إذا بلغ الطفل الثالثة","إذا بلغ الطفل الرابعة","إذا بلغ الطفل السادسة"],"why":"فإذا بلغ الطفل العاشرة، وظلت العدوانية واضحة في سلوكه، فإن على الأهل أن يولوا ذلك اهتمامًا خاصًا خشية تأصل هذا المرض في شخصيته","pg":80},{"q":"كيف يصف الكتاب أثر التدليل المفرط مقارنة بالقسوة في التأديب؟","o":["كلاهما يقوي النزعة العدوانية","التدليل يعالج ما تفسده القسوة","القسوة وحدها تولد العدوانية","التدليل يمنع العدوانية تمامًا"],"why":"وإن التدليل المفرط مثل الإفراط في الضبط والقسوة في التأديب، كلاهما يؤدي إلى تقوية النزعة العدوانية لدى الطفل.","pg":81},{"q":"اعتدى ابنك على أخيه الصغير ليلفت انتباهك. ما الذي يقترحه الكتاب؟","o":["تجاهل فعله ومواساة أخيه","معاقبته أمام إخوته فورًا","الانشغال به ونصحه طويلًا","تركهما حتى يتعبا من العراك"],"why":"فإن تجاهل تصرفاته العدوانية يساعد على تقليلها؛ وذلك لأن الطفل قد يعتدي على غيره بهدف لفت الأنظار إليه","pg":83}],"scene":{"t":"يأخذون قلمي","x":"يشكو ابنك من زميل يأخذ أدواته دون إذن، ويسألك: هل أضربه حتى يكف؟","opts":["تعلمه أن يطالب بحقه بهدوء وعزيمة، فإن رفض شكاه للمعلم","تأمره أن يأخذ حقه بيده حتى لا يستضعفه أحد","تطلب منه السكوت والتنازل حتى لا يتورط"],"why":"المهم ألا تفرِّط بحقك، وألا تشعر أن من السهل الاعتداء عليك، كما أن من المهم يا بني ألا تشتم ولا تسب ولا تضرب.","pg":85}},{"k":"c7","t":"الطفل العنيد","q":"كيف نفرق بين العناد الطبيعي والعناد الذي يحتاج علاجًا؟","essence":"العناد مكتسب، يعالجه اللطف والتعليل والحزم","kw":["العناد","التعليل","العقاب"],"sections":[{"t":"ما العناد ومتى يظهر؟","pg":92,"key":"فالدراسات تشير إلى أن العناد كثيرًا ما يظهر لدى الأطفال بعد سن الثانية والنصف، ويشتد خلال السنة الثالثة والرابعة، ويبدأ بالتلاشي عند سن الخامسة إذا أحسن الأبوان التعامل معه","p":[],"items":[{"h":"الطفل المطيع","x":"هو الذي يفعل ما يطلبه أبوه وأمه في الوقت المحدد، وللعناد ألوان: الرفض، والتأخير، والتثاقل والتذمر، والاستعداد لضرب من يأمره."},{"h":"ذروة العناد","x":"أن يفعل الطفل عكس ما يطلب منه، كأن يؤمر بالكف عن الكلام فيصرخ."}]},{"t":"عناد طبيعي وعناد يحتاج علاجًا","pg":92,"key":"فالطفل حين يُبدي قدرًا معقولًا ومألوفًا من الممانعة والعصيان يرسل إلينا رسالة مضمونها: أنه بدأ يشعر بنفسه","p":["إن علينا ألا نبدي الابتهاج إذا رأينا الطفل مستكينًا مطيعًا، لا يكاد يفارق والدته... فهذا قد يدل على تأخر في نموه النفسي والعقلي."],"items":[{"h":"مظاهر العناد المقلق","x":"رفض الأوامر، والتلكؤ في المهام، وسلوكيات غير لائقة، والغضب لأتفه الأسباب، والتعدي على الآخرين، ورفض التفاوض، والتسلط على الخدم."}]},{"t":"أسباب العناد","pg":95,"key":"ولهذا فإنه كلما كثرت المواقع التي يصطدم بها زادت درجة العناد لديه","p":[],"items":[{"h":"تقييد الحركة","x":"قيود مادية كضيق المنزل وكثرة التحف الممنوعة، وقيود معنوية كعدم محاورة الطفل وضعف الاهتمام به."},{"h":"الشعور بالضعف والظلم","x":"يأتي العناد من شعوره بأنه مظلوم أو ممتهن، أو من التوجيهات المثالية والمطالب التعجيزية."},{"h":"عدم تلبية الحاجات الملحة","x":"الجائع يحتاج إلى الطعام والمرهق إلى الراحة، وقد يظهر العناد حتى تقضى حاجته."},{"h":"تقليد الكبار","x":"من يرى أخاه الكبير يرفض طلبات أبيه يظن ذلك هو السلوك اللائق بالكبير."},{"h":"الحالة النفسية السيئة","x":"كالغيرة الشديدة من أخ أو الإحباط أو الملل."}]},{"t":"بيئة تربوية ملائمة","pg":98,"key":"حين نستجيب لطلبات الطفل المعتدلة والمعقولة، فإننا نجعله يشعر في أعماقه بالامتنان لنا","p":["فقد تبين لنا من الحديث عن أسباب العناد أنه مكتسب بسبب التعامل الخاطئ مع الطفل وبسبب الظروف غير المواتية التي يعيش فيها"],"items":[{"h":"التواصل المستمر","x":"تخصيص الأب وقتًا يوميًا ولو عشر دقائق لمداعبة أولاده والسؤال عن أحوالهم يقلل رفضهم لما يطلبه."},{"h":"الخطاب اللطيف","x":"الطلب بلطف لا يثير روح العناد، كالأب الذي كان يقول لابنه: لو سمحت يا خالد."},{"h":"لا للحشر في الزاوية","x":"بدل الأمر الصارم الفوري تقول الأم: بقي لذهابك إلى غرفة النوم عشر دقائق."},{"h":"فضيلة التعليل","x":"لتعليل الأوامر فائدتان: حفظ كرامة الطفل، وتدعيم التفكير السببي، مع أن يعرف الطفل أن عليه الإذعان لنظام الأسرة."}]},{"t":"التجاهل والمكافأة والعقاب","pg":103,"key":"إذا كانت (المكافأة) تجعل الطفل يشعر بفوائد الطاعة، فإن (العقاب) يجعله يشعر بأضرار العناد","p":["لا يستغني أي مربٍّ مهما كان ابنه هادئًا ومتفهمًا عن استخدام العقاب في بعض الأحيان، والذي لا يعني بالضرورة الضرب واستخدام العنف."],"items":[{"h":"التجاهل","x":"أن نغض الطرف عن الموقف المعاند وكأن شيئًا لم يكن، كابن الخامسة الذي يترك المائدة ثم يعود حين لا يطلبه أحد."},{"h":"الثناء على الامتثال","x":"قدرة العقل على إدراك السلبيات أعظم من إدراك الإيجابيات، فعلينا أن نثني على كل امتثال يظهره الطفل."},{"h":"تجربة والد سعد","x":"قواعد معلنة: النوم في التاسعة، وكل ربع ساعة تأخير يقدم موعد الغد عشرين دقيقة، والحرمان من مصروف يوم أو من الخروج، فتخلص الولد من 70% من عناده في شهرين أو ثلاثة."},{"h":"لا نعده مؤقتًا","x":"إهمال معالجة العناد قد يجعل الطفل عدوانيًا أو مضطربًا نفسيًا حتى بعد العشرين."}]}],"quiz":[{"q":"طفل في الثالثة يرفض بعض أوامر أمه رفضًا معقولًا مألوفًا. كيف يفسره الكتاب؟","o":["بداية شعوره بنفسه ورغبته في الاستقلال","علامة مبكرة على اضطراب نفسي خطير","أثر مباشر لقسوة الأبوين في معاملته","دليل على تأخر واضح في نموه النفسي والعقلي"],"why":"فالطفل حين يُبدي قدرًا معقولًا ومألوفًا من الممانعة والعصيان يرسل إلينا رسالة مضمونها: أنه بدأ يشعر بنفسه","pg":92},{"q":"علام قد يدل الطفل المستكين المطيع الذي لا يكاد يفارق والدته؟","o":["تأخر في نموه النفسي والعقلي","نجاح الأبوين الكامل في تربيته","قوة شخصيته وثقته بنفسه","تعلق صحي يزول مع الكبر"],"why":"إن علينا ألا نبدي الابتهاج إذا رأينا الطفل مستكينًا مطيعًا، لا يكاد يفارق والدته... فهذا قد يدل على تأخر في نموه النفسي والعقلي.","pg":92},{"q":"أي العبارات الآتية تمثل البديل الذي يقترحه الكتاب لحشر الطفل في الزاوية الضيقة؟","o":["بقي لذهابك إلى غرفة النوم عشر دقائق","اذهب إلى غرفتك الآن ولا تناقشني","إن لم تنم فورًا فستعاقب غدًا","نم الآن كما ينام إخوتك المطيعون"],"why":"الأسلوب الجيد هو ما كانت تتَّبعه إحدى الأمهات حين كانت تقول لابنها: بقي لذهابك إلى غرفة النوم عشر دقائق","pg":100},{"q":"ما الفائدتان اللتان يذكرهما المؤلف لتعليل الأوامر للطفل؟","o":["حفظ كرامته وتدعيم تفكيره السببي","إسقاط حق الأب في الإلزام والمحاسبة","تأجيل التنفيذ وإتاحة الجدال الطويل","زيادة مصروفه وتقليل عقوباته"],"why":"الأولى: حفظ كرامة الطفل ومراعاة مشاعره","pg":100},{"q":"ما الخطأ الذي يحذر منه الكتاب في النظر إلى عناد الطفل؟","o":["عدّه أمرًا مؤقتًا يزول وحده","الثناء على كل امتثال منه","تخصيص وقت يومي للتواصل معه","استعمال عقوبة لا ضرب فيها"],"why":"إن من المهم ألا ننظر إلى عناد الطفل على أنه شيء مؤقت سوف يزول حين يبلغ السادسة أو السابعة","pg":104}],"scene":{"t":"ترك المائدة","x":"رفض ابنك ابن الخامسة طعام الغداء، فترك المائدة وتمدد على الأرض غاضبًا.","opts":["تتجاهل موقفه ولا يطلب منه أحد العودة","تحمله إلى المائدة وتجبره على الأكل","تعده بحلوى كبيرة إن عاد إلى المائدة"],"why":"وحين يشعر أنه لا أحد طلب منه العودة إلى المائدة، وأن الطعام أشرف على النفاد يعود إلى المائدة ويبدأ بالأكل.","pg":102}},{"k":"c8","t":"الأنانية","q":"من أين تأتي أنانية الطفل، وكيف ننمي فيه المشاركة؟","essence":"الأنانية مكتسبة، تعالجها المشاركة والتعاطف","kw":["التمركز حول الذات","اللعب الجماعي","التعاطف"],"sections":[{"t":"ما الأنانية؟","pg":106,"key":"الأنانية أو (التمركز حول الذات) هي ذلك الحب المفرط للذات، والحب المفرط لتملك الأشياء والاستيلاء عليها مع عدم الموافقة على إشراك أي شخص آخر للانتفاع بها","p":["تشتد الأنانية لدى الطفل في عامه الثالث وعامه الرابع، ويكون مؤمنًا بقوة في المشاركة في عامه السابع وعامه الثامن."],"items":[{"h":"أثر التقدم المادي","x":"من طبيعة التقدم المادي والعمراني أنه يزيد الأنانية وحب الاستحواذ لدى الكبار، والصغار يتعلمون ذلك منهم."},{"h":"مفهوم الطفل الأول","x":"في الأشهر الثمانية عشر الأولى يتصرف وفق مفهوم: كل ما تقع عيني عليه وكل ما تصل يدي إليه فهو ملكي."},{"h":"لماذا نهتم بها؟","x":"لمعاناة الأهل منها في السنوات الست الأولى، ولإمكان ترسخها فيصبح الطفل شحيحًا لا يفكر إلا في مصلحته."}]},{"t":"أسباب الأنانية","pg":107,"key":"يشير بعض الدراسات إلى أن تأثير الوراثة في الأنانية محدود، وأن الطفل يتعلم السلوك الأناني من أسرته على نحو أساسي، ثم من البيئة التي يعيش فيها","p":[],"items":[{"h":"مكتسب اجتماعي","x":"الأمهات الفاضلات يشجعن الصغير على أن يطعم أبناء الضيوف ويسمح لهم باللعب بدراجته، ثم يمطرنه بالقبلات والثناء."},{"h":"الشعور بالضعف والإهمال","x":"المهمل يتقوقع على نفسه وأشيائه، ويقول في نفسه: ما دام الجميع مشغولين بأنفسهم فلماذا لا أكون كذلك؟"},{"h":"الدلال الزائد","x":"الطفل المدلل يتلقى عناية زائدة وحماية مبالغًا فيها، فيشعر أنه محور اهتمام الآخرين."}]},{"t":"تنمية روح المشاركة","pg":110,"key":"إن (اللعب الجماعي) من أفضل ما ينمّي روح المشاركة","p":[],"items":[{"h":"ماذا يعلمه اللعب الجماعي؟","x":"يعرف الطفل بمعنى التعاون والعدل وبذل الجهد، ويضعف تمحوره حول ذاته."},{"h":"مكان للعب","x":"من وسع الله عليه فليخصص مكانًا مناسبًا للعب، وليرحب بأصدقاء الطفل وأبناء الجيران."}]},{"t":"الثقة بالنفس","pg":111,"key":"وإنما نقول هذا الكلام لأن كثيرًا من المواقف الأنانية يكون عبارة عن تعويض عن الإحساس بالنقص تجاه بعض الأمور.","p":["على الأبوين إلى جانب الثناء والتحفيز تقبل الطفل على ما هو عليه، وهذا هو المعنى العميق للحب غير المشروط"],"items":[{"h":"الحديث عن المزايا","x":"على الأبوين والمعلمين أن يحدثوا الطفل عن نقاط قوته، كطلاقة الحديث أو الابتسامة أو الترحيب بالضيوف أو حفظ القرآن أو المطالعة."}]},{"t":"احترام الآخرين والتعاطف","pg":112,"key":"إن التعاطف مع الناس وسيلة أخرى لمعالجة الأنانية لدى الطفل، التعاطف يعني أن نفهم الآخرين، ونتفاعل مع ظروفهم وأوضاعهم وفق رؤيتهم لها","p":["إن علاج الأنانية لدى الطفل يمكن أن يكون مدخلًا لتحسين الوضع الأخلاقي للأسرة كلها"],"items":[{"h":"قيمة كل إنسان","x":"أب استغل غياب عمال النظافة وتكدس الأوساخ ليوضح لأولاده أنه ليس هناك شخص أو تخصص غير مهم."},{"h":"المؤمنون إخوة","x":"أب كان يذكر أبناءه بأن المؤمن يحب الخير لأخيه، وأن في الناس من هو أفضل منا دينًا وخلقًا."},{"h":"قصة العاملة","x":"حين عرف الأولاد ظروف العاملة اليتيمة التي تعول والدتها المريضة زاد تعاطفهم وصاروا يطلبون زيادة أجرتها."}]}],"quiz":[{"q":"ما المصدر الأساسي لأنانية الطفل كما تشير إليه الدراسات في الكتاب؟","o":["أسرته ثم البيئة التي يعيش فيها","الوراثة التي ينقلها أحد الأبوين","طبيعة السن التي لا تتغير أبدًا","المدرسة ورفاق الفصل وحدهم"],"why":"يشير بعض الدراسات إلى أن تأثير الوراثة في الأنانية محدود، وأن الطفل يتعلم السلوك الأناني من أسرته على نحو أساسي، ثم من البيئة التي يعيش فيها","pg":107},{"q":"في أي سن تشتد الأنانية لدى الطفل؟","o":["في عامه الثالث والرابع","في عامه السابع والثامن","في عامه الأول والثاني","في عامه العاشر وما بعده"],"why":"تشتد الأنانية لدى الطفل في عامه الثالث وعامه الرابع، ويكون مؤمنًا بقوة في المشاركة في عامه السابع وعامه الثامن.","pg":106},{"q":"طفل يشعر أنه مهمل وأن كل من حوله منشغلون بأنفسهم. كيف يؤثر ذلك فيه بحسب الكتاب؟","o":["يتقوقع على نفسه ويهتم بأشيائه","يصبح أكثر كرمًا ليلفت الانتباه","يتعلم الاستقلال فيقل عناده","يميل إلى اللعب الجماعي تعويضًا"],"why":"حين يشعر الطفل بأنه ضعيف أو مهمَل من قبل المحيطين به، فإن من المتوقع أن يتقوقع على نفسه ويهتم بشخصيته وأشيائه","pg":108},{"q":"ما الذي يعده الكتاب من أفضل ما ينمي روح المشاركة لدى الطفل؟","o":["اللعب مع الأصدقاء في فريق","الوعظ المتكرر عن فضل الكرم","حرمانه من ألعابه الخاصة","مكافأته على كل عطاء مادي"],"why":"إن (اللعب الجماعي) من أفضل ما ينمّي روح المشاركة","pg":110},{"q":"لماذا يربط الكتاب بين علاج الأنانية وتقوية الثقة بالنفس؟","o":["لأن كثيرًا من الأنانية تعويض عن النقص","لأن الواثق بنفسه لا يحتاج إلى أصدقاء","لأن الثقة تأتي من كثرة امتلاك الأشياء","لأن الأنانية تنتج عن الذكاء المرتفع"],"why":"وإنما نقول هذا الكلام لأن كثيرًا من المواقف الأنانية يكون عبارة عن تعويض عن الإحساس بالنقص تجاه بعض الأمور.","pg":111}],"scene":{"t":"ألعاب الضيوف","x":"زارك ضيوف معهم أطفال، فرفض ابنك أن يقترب أحد منهم من ألعابه وبدأ يبكي.","opts":["تشجعه برفق على مشاركتهم وتغمره بالثناء حين يفعل","تنتزع الألعاب منه وتعطيها للضيوف عقابًا له","تترك الأمر لأنه سيتخلص من أنانيته وحده"],"why":"وحين يفعل ذلك فإنها تُمطِره بوابل من القبلات وكلمات الثناء","pg":108}},{"k":"c9","t":"الخجل","q":"كيف نميز الخجل من الحياء، وكيف نساعد الطفل الخجول؟","essence":"الخجل يعالج بتجفيف منابعه وتدريب الطفل","kw":["الحياء","الحماية الزائدة","الألقاب"],"sections":[{"t":"الخجل والحياء","pg":115,"key":"هو درجة عالية من الارتباك والخوف والانكماش، يشعر بها الطفل حين يلتقي بأشخاص من خارج محيطه","p":["إن كل هذا ممدوح ومرغوب فيه."],"items":[{"h":"الحياء ممدوح","x":"الحياء شعبة من الإيمان ويعبر عن السمو، كأن يستحيي الطفل من خلع ملابسه أمام والديه أو يجد حرجًا في التحدث أمام الكبار."},{"h":"ظاهرة واسعة","x":"يورد المؤلف أن نحو 40% من المراهقين والراشدين يذكرون أنهم يشعرون بالخجل في مواقف اجتماعية."}]},{"t":"مظاهر الخجل","pg":116,"key":"من النادر أن يكون الطفل الخجول مشاغبًا أو مصدرًا للمشكلات؛ ولهذا فإنه لا يلفت إليه الأنظار","p":[],"items":[{"h":"تجنب اللقاء","x":"يتجنب الناس من خارج أسرته، ويتحاشى النظر إلى من يحدثه."},{"h":"نشيط داخل البيت فقط","x":"قد يكون منفتحًا في المنزل منطويًا خارجه، وقد يدفن رأسه في حجر أمه."},{"h":"ضعف المبادرة","x":"ثقته منخفضة، ولا يقدم على التطوع، وينسحب من المواجهة."},{"h":"في الصف","x":"يجد صعوبة في طرح الأسئلة والإجابة، ويجلس في الزوايا ويتكلم بصوت منخفض."},{"h":"حساسية وقلة خبرة","x":"شديد الحساسية للنقد، ولا ينخرط في الألعاب الجماعية فيقل ما يكتسبه من خبرة وثناء."}]},{"t":"أسباب الخجل","pg":117,"key":"إن للوراثة أثرًا واضحًا في مشكلة الخجل لدى الأطفال، والمشاهدة تؤكد ذلك","p":[],"items":[{"h":"فسيولوجية الدماغ","x":"يرى بعض العلماء أنها تهيئ بعض الأطفال لاستجابة الخجل."},{"h":"الافتقار إلى الأمن","x":"الخلافات المستمرة بين الأبوين، وانشغالهما عن الطفل، والحماية الزائدة التي ترسل إليه أنه لا يستطيع تدبير شؤونه، ونبزه بالألقاب والسخرية منه."},{"h":"الإعاقة","x":"عيوب النطق كالتأتأة والفأفأة أو فقد حاسة تجعل الطفل حساسًا فيبتعد عن الغرباء."},{"h":"تحالف الوراثة مع التربية","x":"الطفل بين أبوين خجولين يقل تواصل أسرته مع المحيط، فينتقل إليه ذلك."}]},{"t":"القراءة والمراجعة","pg":121,"key":"حيث إن الخجل لم يصبح عادة له إلا بسبب بعض المعتقدات لديه وبسبب رؤيته لنفسه وللناس من حوله","p":["المهم ألا نضخّم المشكلة، فنيأس من معالجتها، وألا نهملها فتكبر، وتصبح خارج السيطرة."],"items":[{"h":"قراءة أفكار الطفل","x":"إن كان يخجل من الضيوف لأنه لا يعرف كيف يحييهم علمناه كلمات الاستقبال والتوديع، وإن خجل من السؤال لعيب في النطق عالجناه."},{"h":"مراجعة الجو الأسري","x":"تفحص ما يحيط بالطفل من تدليل زائد أو نقد شديد أو إهمال، لأن التخلص من المشكلة يستلزم تجفيف منابعها."}]},{"t":"تدريب الطفل الخجول","pg":122,"key":"لا تسمح لأحد في الأسرة أن يطلق على الطفل بعض الألقاب التي يمكن أن ترسّخ المشكلة لديه","p":["حيث إن كثرة سماع الطفل لهذه الألفاظ تجعله يصدّقها، وبعد ذلك يتصرف وفق معانيها."],"items":[{"h":"الأنشطة الاجتماعية","x":"الانتساب إلى الحركة الكشفية أو اللجان العلمية، والانخراط في ألعاب جماعية مع طفلين أو ثلاثة مع المكافأة."},{"h":"القيادة والمبادرة","x":"أسر تعقد اجتماعًا كل خمسة عشر يومًا لتدريب الأبناء على الخطابة والأناشيد والحوار، كحوار المقارنة بين السواك والسيجارة."},{"h":"تحميله المسؤوليات","x":"ترك الحرية له في الاتصال بالأصدقاء والأقرباء، وتكليفه بشراء حاجات المنزل ليكسر حاجز الخوف."},{"h":"حديث النفس الإيجابي","x":"إحلال عبارات مثل: أنا قوي، كل الناس يخطئون ويتعلمون من أخطائهم، محل أفكار الضعف."}]}],"quiz":[{"q":"ما الفرق الذي يقرره الكتاب بين الحياء والخجل؟","o":["الحياء ممدوح والخجل ارتباك وانكماش","الحياء مرض والخجل خلق محمود","كلاهما اسم لشيء واحد مذموم","الخجل يزول وحده والحياء لا يزول"],"why":"هو درجة عالية من الارتباك والخوف والانكماش، يشعر بها الطفل حين يلتقي بأشخاص من خارج محيطه","pg":115},{"q":"لماذا قد يعاني الطفل الخجول دون أن ينتبه إليه أحد؟","o":["لأنه نادرًا ما يشاغب فلا يلفت الأنظار","لأنه يكثر الشكوى فيمل منه الكبار","لأنه يرفض كل مساعدة تعرض عليه من الكبار","لأن أهله يعدون خجله حياء ممدوحًا"],"why":"من النادر أن يكون الطفل الخجول مشاغبًا أو مصدرًا للمشكلات؛ ولهذا فإنه لا يلفت إليه الأنظار، ويعاني مع مشكلاته الشخصية دون أن ينتبه إليه أو يساعده أحد.","pg":116},{"q":"أي التصرفات الآتية يعده الكتاب من أسباب الخجل؟","o":["إبقاء الطفل بجوار أبويه خوفًا عليه","تكليفه بشراء بعض حاجات المنزل","تشجيعه على الانضمام إلى الكشافة","تدريبه على الخطابة في اجتماع الأسرة"],"why":"بعض الآباء يحمون أطفالهم حماية زائدة، إنهم يخافون عليهم من كل شيء، ويريدون منهم أن يظلوا إلى جوارهم","pg":118},{"q":"يناديه إخوته «الخجول» على سبيل المزاح. ما موقف الكتاب؟","o":["يمنع ذلك لأن الطفل يصدق ما يسمعه","يتركه لأنه مزاح بريء لا أثر له","يشجعه ليتعود الطفل على تحمل النقد","يكتفي بنصح الطفل أن يتجاهله"],"why":"حيث إن كثرة سماع الطفل لهذه الألفاظ تجعله يصدّقها، وبعد ذلك يتصرف وفق معانيها.","pg":122},{"q":"ما أول عمل يقترحه المؤلف في معالجة الخجل؟","o":["القراءة والمراجعة","الحركة الكشفية","استشارة الطبيب","المكافأة والعقوبة"],"why":"أعتقد أن أول عمل علينا أن نقوم به في معالجة الخجل هو القراءة والمراجعة","pg":121}],"scene":{"t":"لا أعرف ماذا أقول","x":"ابنك يتهرب من الجلوس مع الضيوف، وحين سألته قال: لا أعرف ماذا أقول لهم.","opts":["تعلمه كلمات يقولها في الاستقبال والتوديع والمسامرة","تجبره على الجلوس معهم حتى يتعود","تعفيه من لقاء الضيوف حتى يكبر"],"why":"لأنه لا يعرف كيف يحييهم علَّمناه بعض كلمات يقولها عند استقبالهم وتوديعهم وخلال مسامرته لهم","pg":121}},{"k":"c10","t":"التبول اللاإرادي","q":"متى يكون التبول الليلي مشكلة، وكيف نعالجه بحكمة؟","essence":"اهتمام بلا قلق، وتدريب ومكافأة","kw":["التبول الليلي","قلق الوالدين","المكافأة"],"sections":[{"t":"تعريف المشكلة وحدودها","pg":125,"key":"نقصد بالتبول اللا إرادي: عدم قدرة الطفل على التحكم بالتبول ليلًا في سن يُفترَض أن تكون لديه فيها القدرة على ذلك.","p":["ولا نستطيع أن نقول: إن الطفل يعاني من مشكلة التبول اللا إرادي إلا إذا تجاوز سن الرابعة"],"items":[{"h":"مراحل التحكم","x":"ابن الثمانية عشر شهرًا قابل للتدريب، وغالب الأطفال يتحكمون بأنفسهم في آخر السنة الثالثة."},{"h":"الانتشار كما يورده المؤلف","x":"واحد من كل أربعة أطفال بعد الرابعة إلى الثامنة، ثم نحو 2% لدى صغار الراشدين، وهي أكثر لدى الذكور."},{"h":"الجرح النفسي","x":"قد تترك جرحًا غائرًا في شخصية الطفل، ولا سيما إذا عرف زملاؤه أو أقرباؤه."}]},{"t":"أسباب التبول","pg":126,"key":"وهذه الأسباب قليلة الانتشار وقد لا تشكّل أكثر من (5%) من بين الأسباب التي يتحدث عنها الأطباء والتربويون.","p":[],"items":[{"h":"أسباب عضوية","x":"التهابات في مجرى البول، أو مشكلة في الجهاز البولي أو العمود الفقري، أو مرض السكري."},{"h":"سبب وراثي","x":"تشير دراسات إلى أن المشكلة كانت لدى آباء الأطفال المتبولين بما يقارب ثلاثة أضعاف غيرهم."},{"h":"أسباب نفسية","x":"قسوة الوالدين، والشعور بالنقص، والخوف والقلق كقدوم مولود جديد، والحرمان من الطمأنينة، مع أن ارتباطها بالمشكلة ليس حاسمًا."}]},{"t":"الحذر من التطرف","pg":128,"key":"إن التطرف في كل شيء غير حميد","p":["المهم هو إظهار الاهتمام بالمشكلة، وليس إظهار القلق والتوجس من استمرار المشكلة؛ لأن قلق الوالدين قد ينتقل إلى الطفل، ويؤدي ذلك إلى تفاقم المشكلة عوضًا عن حلها."],"items":[{"h":"طرف الإهمال","x":"بعض الأهل يظنون أن الوضع سيتحسن تلقائيًا، فإذا استمرت المشكلة حتى الخامسة عشرة تركت ندوبًا قد تصاحبه مدى الحياة."},{"h":"طرف القسوة","x":"معاقبة الطفل بالضرب والشتم والألقاب تعمق المشكلة، والمطلوب الاهتمام والتشجيع."}]},{"t":"إجراءات عملية","pg":129,"key":"من المهم أن يمتنع الطفل عن تناول السوائل قبل النوم بثلاث ساعات على الأقل","p":["إن الخوف من الحركة في الظلام ليلًا أمرٌ شائعٌ جدًا بين الأطفال."],"items":[{"h":"السوائل المدرة","x":"ولا سيما القهوة والشاي والمشروبات الغازية."},{"h":"سبب الانتكاس","x":"إذا عاد إلى التبول بعد انقطاع نتعرف على الحادث المثير للقلق كغياب أحد الأبوين أو شجار أو مولود جديد، وتجلس الأم معه عشر دقائق قبل النوم بحديث مطمئن."},{"h":"قرب الحمام والضوء","x":"إن كان الحمام بعيدًا يستحسن ضوء خافت في الغرفة والطريق إليه."},{"h":"الإمساك والاستيقاظ","x":"التأكد من عدم وجود إمساك، وتدريبه على الاستيقاظ بعد ساعتين من نومه ثم بالساعة المنبهة حين يكبر."}]},{"t":"المكافأة والعقوبة والطبيب","pg":131,"key":"المكافأة والعقوبة من الأمور المهمة في تخلي الأطفال عن العادات السيئة","p":[],"items":[{"h":"نجوم الليالي الجافة","x":"نجمة عن كل ليلة جافة، وعشرون نجمة إذا مضى أسبوعان، وتجمع شهريًا مقابل جائزة."},{"h":"عقوبة مناسبة","x":"ابن التاسعة قد يحمل ما تبلل من ملابسه إلى الغسالة، أو يخصم جزء من مصروفه، أو يحرم من الخروج."},{"h":"استشارة طبيب متخصص","x":"لاحتمال وجود أمراض عضوية، ولا سيما عند إخفاق كل المحاولات."}]}],"quiz":[{"q":"متى يمكن القول إن الطفل يعاني من مشكلة التبول اللاإرادي؟","o":["إذا تجاوز سن الرابعة","إذا تجاوز سن الثانية","إذا بلغ آخر الثالثة","إذا تجاوز سن الثامنة"],"why":"ولا نستطيع أن نقول: إن الطفل يعاني من مشكلة التبول اللا إرادي إلا إذا تجاوز سن الرابعة","pg":125},{"q":"ما حجم الأسباب العضوية بين أسباب التبول كما يذكره الكتاب؟","o":["قليلة لا تزيد غالبًا على 5%","كثيرة تزيد على نصف الحالات","متوسطة تقارب ربع الحالات","غالبة تبلغ 85% من الحالات"],"why":"وهذه الأسباب قليلة الانتشار وقد لا تشكّل أكثر من (5%) من بين الأسباب التي يتحدث عنها الأطباء والتربويون.","pg":126},{"q":"والدان يتابعان تبول طفلهما بقلق ظاهر وسؤال دائم. ما خطورة ذلك؟","o":["قلقهما قد ينتقل إليه فتتفاقم المشكلة","يطمئن الطفل فيتوقف التبول سريعًا وتلقائيًا","لا أثر له ما دام دون عقاب أو ضرب","يعلمه الاعتماد على نفسه في الليل"],"why":"لأن قلق الوالدين قد ينتقل إلى الطفل، ويؤدي ذلك إلى تفاقم المشكلة عوضًا عن حلها.","pg":129},{"q":"عاد طفل إلى التبول في فراشه بعد أن انقطع عنه مدة. بم يوصي الكتاب؟","o":["التعرف على ما أثار قلقه وخوفه","زيادة العقوبة حتى لا يعود إليه","منعه من شرب الماء طوال اليوم","إهمال الأمر لأنه سيزول وحده"],"why":"أحيانًا يكف الطفل عن التبول في فراشه مدة من الزمن، ثم يعود إليه، وفي هذه الحالة فإن من المفيد جدًا أن نتعرف على أسباب ذلك","pg":129},{"q":"كيف يرى الكتاب العقوبة في علاج التبول لدى ابن التاسعة؟","o":["ممكنة، كحمل ملابسه إلى الغسالة","ممنوعة مطلقًا في كل الأعمار","مقدمة على المكافأة في كل حال","تكون بالتوبيخ الشديد أمام إخوته"],"why":"وإن ابن التاسعة قد يعاقَب بأن يأخذ ما تبلل من ملابسه ومن الشراشف إلى الغسالة، ليقوم هو بغسلها","pg":131}],"scene":{"t":"الممر المظلم","x":"ابنك ابن السادسة يبلل فراشه، والحمام في آخر ممر مظلم بعيد عن غرفته.","opts":["تبقي ضوءًا خافتًا في غرفته وفي الطريق إلى الحمام","تطفئ الأضواء كلها ليتعود على الشجاعة","توبخه صباحًا حتى يتحمل مسؤولية فعله"],"why":"فإن من المستحسن الإبقاء على ضوء خافت في غرفة الطفل وفي الطريق الموصل إلى الحمام","pg":130}}],"highlights":[{"x":"الأصل في تغيير عادات الأطفال المكافأة لا العقوبة","pg":7},{"x":"نبني ثقة أبنائنا بنا من خلال الحرية، وليس من خلال الضغوط","pg":8},{"x":"الأطفال يحتاجون إلى القدوة وليس إلى الانتقاد","pg":10},{"x":"إذا كان الولد سر أبيه، فعلى الآباء أن يهذبوا أنفسهم قبل تهذيب أبنائهم","pg":18},{"x":"لا تصبح الأم أمًا حين تلد، ولكن حين تربي","pg":26},{"x":"كل مشكلة توصَّف توصيفًا جيدًا هي مشكلة محلولة جزئيًا","pg":54},{"x":"النقد أمام الآخرين يجرح ولا يعالج","pg":63},{"x":"الشيء إذا زاد على حده انقلب إلى ضده","pg":67},{"x":"كثرة غضب المربي تجعل ممن يربيه شخصًا عنيدًا متمردًا","pg":85},{"x":"التربية الجيدة هي التربية التي تقوم على الفعل، وليس على رد الفعل، وعلى المعرفة، وليس على العشوائية","pg":95},{"x":"إذا لم نتحدث مع أطفالنا في المسائل الصغيرة، لم نعرف ما لديهم في المسائل الكبيرة","pg":108},{"x":"المربي الأكثر نجاحًا هو المربي الأقل استخدامًا للعقوبات","pg":131}],"concepts":[{"term":"الكذب","def":"مخالفة كلام الإنسان لما يعتقده بقصد التضليل وإخفاء الحقيقة","pg":11},{"term":"الدافع","def":"الدافع هو طاقة كامنة لدى الطفل تحركه في اتجاه سلوك معين","pg":22},{"term":"المدرسة الجيدة","def":"المدرسة الجيدة هي المدرسة التي يتوفر فيها شيئان أساسيان: جدية في التعليم، وشعور المدرسين فيها بالرضا عن أوضاعهم وأوضاع مدرستهم","pg":27},{"term":"النشاط الزائد","def":"النشاط الزائد هو حركات جسمية تفوق الحد الطبيعي أو المعتاد","pg":31},{"term":"العدل بين الأبناء","def":"العدل بين الأبناء لا يعني المساواة، ولكنه يعني إعطاء كل واحد منهم ما يحتاجه بالمعروف","pg":51},{"term":"الشعور بالدونية","def":"إن الشعور بالدونية هو مجموعة الصور السلبية التي يختزنها الطفل في ذاكرته عن ذاته","pg":57},{"term":"العدوان الجسدي","def":"يتمثل العدوان الجسدي في إيذاء الطفل لجسد طفل آخر أو إيذاء شخص راشد","pg":74},{"term":"العدوان الكلامي","def":"يقتصر العدوان الكلامي على استخدام اللسان في الشتم والقذف والوصف بالأوصاف التي تحمل طابع الإهانة","pg":75},{"term":"العدوان الرمزي","def":"إنه ذلك النوع من العدوان الذي لا تُستخدَم فيه اليد ولا اللسان، لكن يستخدم فيه النظر، ويظهر في المواقف","pg":76},{"term":"الطفل المطيع","def":"الطفل المطيع هو الذي يفعل ما يطلبه منه أبوه، وما تطلبه منه أمه في الوقت المحدد","pg":91},{"term":"التجاهل","def":"نعني بالتجاهل أن نغض الطرف عن الموقف المعاند للطفل، وكأن شيئًا لم يكن","pg":102},{"term":"الأنانية","def":"الأنانية أو (التمركز حول الذات) هي ذلك الحب المفرط للذات، والحب المفرط لتملك الأشياء والاستيلاء عليها مع عدم الموافقة على إشراك أي شخص آخر للانتفاع بها","pg":106},{"term":"الحب غير المشروط","def":"على الأبوين إلى جانب الثناء والتحفيز تقبل الطفل على ما هو عليه، وهذا هو المعنى العميق للحب غير المشروط","pg":111},{"term":"التعاطف","def":"التعاطف يعني أن نفهم الآخرين، ونتفاعل مع ظروفهم وأوضاعهم وفق رؤيتهم لها","pg":112},{"term":"الخجل","def":"هو درجة عالية من الارتباك والخوف والانكماش، يشعر بها الطفل حين يلتقي بأشخاص من خارج محيطه","pg":115},{"term":"التبول اللاإرادي","def":"عدم قدرة الطفل على التحكم بالتبول ليلًا في سن يُفترَض أن تكون لديه فيها القدرة على ذلك.","pg":125}],"links":[{"topic":"الكذب","pg":11},{"topic":"التحفيز والمكافأة","pg":29},{"topic":"العدل بين الأبناء","pg":48},{"topic":"الثقة بالنفس","pg":64},{"topic":"العدوان والعنف","pg":73},{"topic":"الحوار وتعليل الأوامر","pg":100},{"topic":"العقوبة","pg":103},{"topic":"اللعب الجماعي","pg":110},{"topic":"الخجل والحياء","pg":115},{"topic":"البيئة الأسرية","pg":134}]};
